import{z as d,x as A,o as r,c as p,q as l,j as n,D as e,d as s,s as i,S as E,b as t}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"指称语义直觉","description":"","frontmatter":{"title":"指称语义直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/denotational-semantics.md","filePath":"cs/denotational-semantics.md","lastUpdated":1791063341000}'),c={name:"cs/denotational-semantics.md"};function B(m,a,b,f,h,u){const o=A("Mermaid");return r(),p("div",null,[a[2]||(a[2]=l('<h1 id="指称语义直觉" tabindex="-1">指称语义直觉 <a class="header-anchor" href="#指称语义直觉" aria-label="Permalink to &quot;指称语义直觉&quot;">​</a></h1><div class="epigraph"><p>把项映射到数学对象：函数、域上的点、关系。组合性：复合项的含义由部件的含义算出。操作语义给步骤，指称给「是什么」。</p><footer>—— 据 Scott 域论；Stoy, Denotational Semantics；Pierce TAPL 短论；Knaster–Tarski 课的延续整理</footer></div><p>上一课<a href="/cs/operational-semantics">操作语义</a>给出 \\(\\to\\)。缺口是<strong>指称</strong>：\\(\\llbracket t\\rrbracket\\) 是集合论或域里的元素，β 在指称里变成等式。递归要用最小不动点——<a href="/cs/knaster-tarski-fixpoint">Knaster–Tarski</a> 已给格上的工具。本课直觉：为何需要域（不终止），不把完整域论作业写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>操作语义的「等价」是互模拟或上下文等价，难算。指称：两个项含义相同则应可替换（组合性保证合同）。缺口是<strong>含义函数</strong>，不是再列 SOS 规则。</p><p><span class="marginnote">术语翻译：指称语义就是「给每段程序发一张数学身份证」——项 \\(\\llbracket t\\rrbracket\\) 被映射成函数或域上的一个点，程序的含义不靠「怎么一步步执行」描述，而是它等于哪个数学对象。组合性的好处：整句的身份由各部件的身份直接算出，不必把程序重新跑一遍。</span></p><p>不终止：朴素函数集没有 \\(\\bot\\)。Scott：偏序、连续函数，\\(Y\\) 是最小不动点。STLC 无递归则可用完全的集合论函数。</p><h3 id="指称不是「编译到数学的编译器」" tabindex="-1">指称不是「编译到数学的编译器」 <a class="header-anchor" href="#指称不是「编译到数学的编译器」" aria-label="Permalink to &quot;指称不是「编译到数学的编译器」&quot;">​</a></h3><p>它是规范。编译器正确性：\\(\\llbracket\\mathrm{target}\\rrbracket\\) 与 \\(\\llbracket\\mathrm{source}\\rrbracket\\) 相关（后课 CompCert 用操作+模拟更多）。不要把指称当运行时。</p><p><span class="marginnote">Dana Scott。Stoy 的教材。Plotkin 的 ADEQUACY：指称与操作一致。本课不写幂域处理非确定的全文。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>STLC：\\(\\llbracket\\tau\\to\\tau&#39;\\rrbracket=\\llbracket\\tau\\rrbracket\\to\\llbracket\\tau&#39;\\rrbracket\\)，\\(\\llbracket\\lambda x.t\\rrbracket\\) 是函数。带递归：在域上取 \\(\\mathrm{fix}\\)。命令式：状态变换器 \\(\\mathrm{State}\\to\\mathrm{State}\\times\\mathrm{Val}\\)，或用单子。</p>',12)),(r(),n(E,null,{default:e(()=>[i(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E9%A1%B9%22%5D%20--%3E%20D%5B%22%E2%9F%A6t%E2%9F%A7%20%E6%95%B0%E5%AD%A6%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20OP%5B%22%E6%93%8D%E4%BD%9C%20%E2%86%92*%20v%22%5D%20--%3E%20ADQ%5B%22adequacy%22%5D%0A%20%20D%20--%3E%20ADQ%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"与类型：含义可只给良型项定义，健全性变成「含义有定义」。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[s("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"完全抽象：指称相等 iff 上下文等价。PPL 里往往失败（序列化、并行），需精细模型。本课只要知道这是理想，不是免费定理。",-1)),a[6]||(a[6]=t("p",null,"递归之所以需要域而不只是集合，是因为指称要从一张近似的阶梯上把不动点「找出来」：",-1)),(r(),n(E,null,{default:e(()=>[i(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20B%5B%22%E2%8A%A5%EF%BC%9A%E6%B0%B8%E4%B8%8D%E7%BB%88%E6%AD%A2%E7%9A%84%E8%BF%91%E4%BC%BC%22%5D%20--%3E%20A1%5B%22f(%E2%8A%A5)%EF%BC%9A%E5%B1%95%E5%BC%80%E4%B8%80%E5%B1%82%22%5D%0A%20%20A1%20--%3E%20A2%5B%22f(f(%E2%8A%A5))%EF%BC%9A%E5%B1%95%E5%BC%80%E4%B8%A4%E5%B1%82%22%5D%0A%20%20A2%20--%3E%20A3%5B%22%E2%80%A6%E2%80%A6%E9%80%90%E5%B1%82%E9%80%BC%E8%BF%91%22%5D%0A%20%20A3%20--%3E%20FP%5B%22%E6%9C%80%E5%B0%8F%E4%B8%8D%E5%8A%A8%E7%82%B9%EF%BC%9A%E9%80%92%E5%BD%92%E5%87%BD%E6%95%B0%E7%9A%84%E6%8C%87%E7%A7%B0%22%5D%0A%20%20EQ%5B%22%E4%B8%8D%E5%8A%A8%E7%82%B9%E6%96%B9%E7%A8%8B%20fix%20f%20%3D%20f%20(fix%20f)%22%5D%20-.%E5%AE%83%E7%9A%84%E6%9C%80%E5%B0%8F%E8%A7%A3.-%3E%20FP%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">直觉类比：给递归求指称像解方程 \\(x = f(x)\\)。从「什么都不做」的 \\(\\bot\\) 出发，每迭代一次就多展开一层递归，逼近序列 \\(\\bot \\sqsubseteq f(\\bot) \\sqsubseteq f^2(\\bot) \\sqsubseteq \\cdots\\) 的极限就是答案。特意选「最小」的不动点，是为了把一切不终止的行为都归到 \\(\\bot\\)，而不是凭空多送一些值。</span></p><p><span class="marginnote">常见误区：初学者容易把指称语义当成「一份能跑的参考实现」。它是规范而非运行时——只说程序「等于什么」，不说「怎么算」。编译器正确性的表述是源语言与目标语言的指称相容，不是把指称当解释器再跑一遍。</span></p><p>不要用指称去「优化浮点」而不谈 IEEE——指称必须先选数学模型，fast-math 后课会破坏它。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Scott 定理。后课默认：含义可组合；递归靠不动点。下一课抽象解释：在格上近似指称/收集语义，服务分析。</p><p>也不把 UML 当指称语义。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>指称：项 → 数学对象，求组合性。</li><li>不终止与递归需要域与最小不动点。</li><li>adequacy 把指称和操作对齐。</li><li>出处：Scott；Stoy；对照 Plotkin、Pierce；Knaster–Tarski。</li></ul>',8))])}const S=d(c,[["render",B]]);export{D as __pageData,S as default};
